def orientation(p1, p2, p3):
    """Cross product (p2-p1) x (p3-p1)"""
    return (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p2[1] - p1[1]) * (p3[0] - p1[0])

def point_in_triangle(pt, p1, p2, p3):
    """Check if pt is inside (on boundary of) triangle p1-p2-p3"""
    o1 = orientation(pt, p1, p2)
    o2 = orientation(pt, p2, p3)
    o3 = orientation(pt, p3, p1)

    if o1 == 0 and o2 == 0 and o3 == 0:
        return True

    has_neg = False
    has_pos = False
    for o in [o1, o2, o3]:
        if o < 0:
            has_neg = True
        if o > 0:
            has_pos = True
